import json, shutil
from pathlib import Path
p=Path('/workspace/ownvideo/videos/pelantikan-dan-peranan-pegawai-pengurusan-rekod/v001')
data=[
('Gambaran keseluruhan',0,[5,6],['Dokumen rahsia rasmi: empat peranan','Rekod terbuka: dua peranan','Fokus: tugas, kuasa dan prosedur'],'''Video ini menerangkan pelantikan dan peranan pegawai pengurusan rekod berdasarkan dokumen yang dibekalkan. Kandungannya meliputi dua kumpulan, iaitu pengurusan dokumen rahsia rasmi dan pengurusan rekod terbuka. Bagi dokumen rahsia rasmi, terdapat Pegawai Pengelas, Pegawai Pengelas Semula, Pendaftar Rahsia dan Pendaftar Kecil Rahsia. Bagi rekod terbuka pula, terdapat Pegawai Rekod Jabatan dan Pembantu Tadbir Rekod Jabatan. Mari kita lihat perbezaan tugas, pihak yang melantik, serta perkara penting dalam urusan pelantikan mereka.'''),
('Pegawai Pengelas',2,[2,5],['Mengelaskan: Rahsia Besar, Rahsia, Sulit atau Terhad','Seksyen 2B, Akta Rahsia Rasmi 1972 (Akta 88)','Pelantik: Menteri Pendidikan Tinggi'],'''Pertama, Pegawai Pengelas. Tugas utamanya ialah mengelaskan perkara rasmi, maklumat atau bahan kepada peringkat Rahsia Besar, Rahsia, Sulit atau Terhad. Jadual pelantikan dalam sumber menyatakan seksyen dua B, Akta Rahsia Rasmi seribu sembilan ratus tujuh puluh dua, atau Akta lapan puluh lapan, sebagai sumber lantikan. Pihak yang melantik ialah Menteri Pendidikan Tinggi. Jawatan yang dinyatakan termasuk Ketua Jabatan, Timbalan Ketua Jabatan, Ketua Bahagian, serta pegawai awam lain yang difikirkan perlu oleh Ketua Jabatan.'''),
('Prosedur Pegawai Pengelas',2,[3,4],['Permohonan dengan pengesahan Ketua Jabatan','Selepas dilantik: borang maklumat pegawai','KPKK 9 + salinan sijil: dalam 30 hari bekerja','Lulus tapisan keselamatan dan ikuti kursus CGSO'],'''Untuk memohon, gunakan Borang Permohonan Pelantikan Pegawai Awam Sebagai Pegawai Pengelas, dengan pengesahan Ketua Jabatan. Selepas dilantik, lengkapkan borang maklumat pegawai yang telah dilantik di bawah seksyen dua B. Borang K P K K sembilan, bersama salinan sijil perakuan, perlu dikemukakan dalam tempoh tiga puluh hari bekerja dari sijil perakuan. Tarikh lantikan mengikut tarikh sijil perakuan lantikan oleh Menteri. Sumber turut menetapkan keperluan menjalani dan lulus tapisan keselamatan, serta kursus Pegawai Pengelas anjuran C G S O.'''),
('Pegawai Pengelas Semula',1,[2,5],['Kuasa di bawah Seksyen 2C, Akta 88','UiTM Shah Alam: Naib Canselor; cawangan: Rektor','Selepas pengelasan semula, bahan terhenti menjadi rahsia rasmi'],'''Kedua, Pegawai Pengelas Semula. Sumber menerangkan bahawa kuasa ini diberikan melalui seksyen dua C, Akta lapan puluh lapan, dan tidak memerlukan pelantikan. Dalam konteks yang dinyatakan, Ketua Agensi ialah Naib Canselor bagi Universiti Teknologi MARA Shah Alam, dan Rektor bagi cawangan. Peranan pegawai ini ialah mengelaskan semula suratan dalam Jadual kepada Akta tersebut, atau suratan rasmi, maklumat dan bahan yang telah dikelaskan. Selepas pengelasan semula, suratan, maklumat atau bahan berkenaan terhenti menjadi rahsia rasmi.'''),
('Pewakilan kuasa pengelasan semula',1,[2,3],['Menurut Seksyen 5 dan 9, Akta 358','KPKK 9A bersama salinan Warta Kerajaan','Ketua Jabatan → Penasihat Undang-Undang → CGSO'],'''Jika berkaitan, jabatan boleh menetapkan pegawai awam untuk menerima pewakilan kuasa Pegawai Pengelas Semula, menurut seksyen lima dan seksyen sembilan, Akta tiga ratus lima puluh lapan. Jawatan yang dinyatakan termasuk Timbalan Ketua Jabatan serta Ketua atau Pengarah Bahagian. Borang K P K K sembilan A dikemukakan bersama salinan Warta Kerajaan bagi maksud pewakilan kuasa. Urusan diselaraskan oleh Ketua Jabatan, disemak oleh Penasihat Undang-Undang Jabatan, kemudian diserahkan kepada C G S O. Pewakilan diperakukan oleh Menteri melalui Surat Pemberitahuan.'''),
('Pendaftar Rahsia dan Pendaftar Kecil Rahsia',3,[5],['Pendaftar Rahsia: mengurus Buku Daftar Rahsia Rasmi','Pendaftar Kecil Rahsia: mengurus fail terperingkat','Gred 1 ke atas; dilantik Ketua Jabatan/Bahagian/Unit'],'''Seterusnya, Pendaftar Rahsia mengurus Buku Daftar Rahsia Rasmi, termasuk pendaftaran, pengelasan semula dan edaran. Sumber lantikannya ialah perenggan lapan puluh satu, Arahan Keselamatan, Semakan dan Pindaan dua ribu tujuh belas. Pendaftar Kecil Rahsia pula mengurus fail terperingkat di Jabatan, Bahagian atau Unit. Sumber lantikannya ialah Surat Pekeliling Am Bilangan lapan tahun dua ribu dua puluh empat. Bagi kedua-dua peranan, pegawai yang dinyatakan ialah Gred satu ke atas yang berkenaan, dan pelantiknya ialah Ketua Jabatan, Bahagian atau Unit.'''),
('Pengurusan rekod terbuka',5,[6],['PRJ: menyelia pengurusan fail; Gred 9 ke atas','Jika tiada, PRJ boleh dilantik daripada Gred 5 ke atas','PTRJ: mengurus pengurusan fail; Gred 1 ke atas','Pelantik kedua-duanya: Arkib Negara Malaysia'],'''Bagi rekod terbuka, Pegawai Rekod Jabatan, atau P R J, menyelia pengurusan fail di Jabatan, Bahagian atau Unit. Pegawai yang dinyatakan ialah Gred sembilan ke atas. Jika tiada, pegawai Gred lima ke atas boleh dilantik. Pembantu Tadbir Rekod Jabatan, atau P T R J, pula mengurus pengurusan fail dan melibatkan pegawai Gred satu ke atas. Kedua-dua peranan merujuk Panduan Pengurusan Rekod Sektor Awam, Arkib Negara Malaysia, sebagai sumber lantikan. Pihak yang melantik kedua-duanya ialah Arkib Negara Malaysia.'''),
('Pembatalan dan rumusan',0,[3,5,6],['Perubahan jawatan atau penempatan; meninggalkan perkhidmatan','Pelanggaran peraturan/tatatertib atau tidak melaksanakan tugas','Pegawai Pengelas: serahkan kembali sijil kepada BARU/UAC','Kenal pasti peranan, kuasa dan borang yang berkaitan'],'''Akhir sekali, sumber menyenaraikan pembatalan lantikan apabila berlaku perubahan jawatan atau penempatan, bersara, berhenti atau tamat perkhidmatan. Jadual pengurusan rekod turut menyenaraikan pelanggaran peraturan atau tatatertib, serta tidak melaksanakan tugas. Bagi Pegawai Pengelas, perubahan nama juga disenaraikan, bersama penyerahan kembali sijil perakuan kepada B A R U atau U A C. Bagi Pegawai Pengelas Semula dan penerima pewakilan, sumber menyebut pertukaran jabatan atau meninggalkan perkhidmatan. Sebagai rumusan, kenal pasti peranan, kuasa dan borang yang berkaitan supaya urusan pelantikan dapat difahami dengan jelas.''')]
story={'title':'Pelantikan dan Peranan Pegawai Pengurusan Rekod','language':'ms-MY','fps':30,'sources':[{'id':'user_pdf','title':'video unit konsultasi (1).pdf','path':'source/video-unit-konsultasi.pdf'}],'scenes':[]}
for i,(title,role,pages,bullets,narration) in enumerate(data,1):
 s={'id':f's{i:02}','title':title,'role':role,'eyebrow':'PENGURUSAN REKOD • RINGKASAN','layout':'source_cards','bullets':bullets,'narration':narration,'source_refs':[{'source':'user_pdf','section':'Halaman PDF '+', '.join(map(str,pages))}],'animation':'Kad isi muncul berturutan; sari kata mengikut narasi.'}
 story['scenes'].append(s)
 (p/'source'/f's{i:02}-narasi.txt').write_text(narration)
(p/'storyboard.json').write_text(json.dumps(story,ensure_ascii=False,indent=2))
(p/'outputs/Skrip_dan_Storyboard.md').write_text('# '+story['title']+'\n\nSumber tunggal: PDF pengguna. Sasaran: 5–6 minit.\n\n'+'\n\n'.join(f"## {s['id']} — {s['title']}\n\n{s['source_refs'][0]['section']}\n\n{s['narration']}\n\nTeks skrin:\n"+'\n'.join('- '+x for x in s['bullets']) for s in story['scenes']))
shutil.copy('/workspace/attachments/b98fa04c-1a53-4aa0-948f-575d6f6c8af5/video unit konsultasi (1).pdf',p/'source/video-unit-konsultasi.pdf')
